escenas.animacion:
const k=A.k;
const tF=k('fuerte',1.0), tC=k('Chile',2.667), tV=k('Valdivia',3.0), t60=k('1960',3.333), tM=k('magnitud',3.667), t95=k('9,5',4.0);
A.bg('#160a10','#05060c');
const ac=A.accent;
const morph=A.p(tC-0.3,0.75,'whip');
const N=140;
const ampAt=(tt)=> tt<0?0:(16+200*Math.pow(A.clamp((tt-0.5)/2.0),1.6));
const coastX=(f)=>330-50*f+12*Math.sin(f*31)+(f>0.7?9*Math.sin(f*95):0);
const eastX=(f)=>coastX(f)+72-34*f+10*Math.sin(f*7);
const chileY=(f)=>440+f*660;
let sh=9*A.p(tF,1.5,'gentleIn')*(1-morph);
if(t>t95) sh+=22*(1-A.p(t95,0.6,'cruise'));
A.with(()=>{
  if(morph<1){
    A.line([[80,770],[1000,770]],{stroke:'#ffffff',lw:2,alpha:0.15*(1-morph)});
  }
  const pts=[];
  for(let i=0;i<N;i++){
    const f=i/(N-1);
    const sx=80+f*920;
    const tt=t-(1-f)*1.4;
    const n=Math.sin(i*1.7+t*30)*0.6+Math.sin(i*0.63-t*17)*0.4;
    const sy=770+ampAt(tt)*n*(1-morph);
    const cx=coastX(f), cy=chileY(f);
    pts.push([A.lerp(sx,cx,morph),A.lerp(sy,cy,morph)]);
  }
  const pE=A.p(tC+0.25,0.6,'glide');
  if(pE>0){
    const poly=[];
    for(let i=0;i<N;i++){const f=i/(N-1);poly.push([coastX(f),chileY(f)]);}
    for(let i=N-1;i>=0;i--){const f=i/(N-1);poly.push([eastX(f),chileY(f)]);}
    ctx.save();ctx.globalAlpha=pE*0.9;
    A.lib.hatch(ctx,poly,{angle:-0.8,spacing:12,width:1.5,color:ac});
    ctx.restore();
    const ep=[];for(let i=0;i<N;i++){const f=i/(N-1);ep.push([eastX(f),chileY(f)]);}
    A.line(ep,{stroke:'#ffffff',lw:3,alpha:0.8,progress:pE});
    A.text('ANDES',eastX(0.3)+40,chileY(0.3),{size:32,color:'#ffffff',weight:800,align:'left',alpha:pE*0.85});
  }
  A.line(pts,{stroke:ac,lw:6,glow:20});
  // Etiqueta CHILE junto a la costa
  if(t>=tC-0.05){
    const pc=A.p(tC,0.3,'snapSettle');
    A.with(()=>{
      A.text('CHILE',140,1000,{size:42,color:'#ffffff',weight:900,align:'center',alpha:A.clamp(pc*1.5),stroke:'#05060c',strokeWidth:6});
    },{x:140,y:1000,scale:0.85+0.15*pc});
  }
  if(morph<1){
    const lp=pts[N-1];
    A.circle(lp[0],lp[1],12,{fill:'#ffffff',alpha:1-morph,glow:20});
    A.line([[lp[0],lp[1]],[1040,lp[1]]],{stroke:'#ffffff',lw:4,alpha:1-morph});
  }
  const fv=0.58, vx=coastX(fv)+20, vy=chileY(fv);
  if(t>=tV-0.05){
    A.rings(vx,vy,tV,{count:3,speed:260,gap:0.35,maxR:180,color:ac,lw:4});
    if(t>t95) A.rings(vx,vy,t95,{count:4,speed:700,gap:0.12,maxR:600,color:'#ffffff',lw:5});
    const sc=A.pop(tV,0.3);
    A.circle(vx,vy,18*sc,{fill:'#ffffff',glow:30});
    A.circle(vx,vy,30*sc,{stroke:ac,lw:4});
    const pl=A.p(tV,0.25,'glide');
    A.line([[vx+34,vy],[A.lerp(vx+34,620,pl),vy]],{stroke:'#ffffff',lw:3,alpha:0.8});
    const pv=A.p(tV,0.2,'snapSettle');
    A.label('VALDIVIA',790,vy,{size:62,bg:ac,color:'#ffffff',scale:0.92+0.08*pv,alpha:A.clamp(pv*2)});
  }
  if(t>=t60-0.05){
    const p6=A.p(t60,0.45,'snapSettle');
    const yr=String(Math.round(A.lerp(1900,1960,p6)));
    A.text(yr,790,vy+150+(1-p6)*40,{size:130,color:'#ffffff',weight:900,align:'center',alpha:A.p(t60,0.25,'softInOut')});
  }
},{shake:sh});
if(t>=tF-0.05&&t<tM+0.3){
  const a=1-A.p(tM-0.15,0.35,'accelExit');
  A.label('EL MÁS FUERTE',540,1440,{size:64,bg:'#ffffff',color:'#160a10',scale:A.pop(tF,0.45),alpha:a});
}
if(t>=tM-0.15){
  const a=A.p(tM-0.15,0.3,'softLand');
  const pf=A.p(tM,t95-tM+0.02,'snapSettle');
  const bx=140,bw=800,by=1680,bh=30;
  A.rect(bx,by,bw,bh,{r:15,fill:'#ffffff',alpha:0.12*a});
  A.rect(bx,by,Math.max(1,bw*0.95*pf),bh,{r:15,fill:ac,alpha:a,glow:t>t95?40:15});
  for(let i=1;i<=10;i++){
    const x=bx+bw*i/10;
    A.text(String(i),x-bw*0.05,by+62,{size:26,color:'#ffffff',weight:700,align:'center',alpha:0.6*a});
  }
  // marca del 9,5
  const mx=bx+bw*0.95;
  const pm=A.p(t95-0.05,0.3,'snapSettle');
  if(pm>0){
    A.line([[mx,by-16],[mx,by+bh+6]],{stroke:'#ffffff',lw:5,alpha:pm});
    ctx.save();ctx.globalAlpha=pm;ctx.fillStyle='#ffffff';
    ctx.beginPath();ctx.moveTo(mx-12,by-30);ctx.lineTo(mx+12,by-30);ctx.lineTo(mx,by-14);ctx.closePath();ctx.fill();
    ctx.restore();
  }
  const ps=t>=t95?A.pop(t95,0.4):0;
  const val=(Math.round(9.5*pf*10)/10).toFixed(1).replace('.',',');
  A.with(()=>{
    A.text(val,540,1530,{size:110+50*ps,color:t>=t95?ac:'#ffffff',weight:900,align:'center',alpha:a,stroke:'#05060c',strokeWidth:8});
  },{x:540,y:1500,shake:t>t95?10*(1-A.p(t95,0.5,'cruise')):0});
}
if(t>=t95) A.flash(t95,0.3,0.45);

const W=A.W, ac=A.accent;
A.bg('#0b1630','#050a18',true);
const tDom=A.k('domingo',0.667), t22=A.k('22',1.333), tMay=A.k('mayo,',2.0), tTie=A.k('tierra',3.0), tSac=A.k('sacudió',3.667), tDiez=A.k('diez',5.0);
const tMove=tTie-0.45;
// intensidad del sismo
const inten = A.clamp((t-tTie)/0.6)*0.35 + A.clamp((t-tSac)/0.5)*0.45 + A.clamp((t-tDiez)/0.3)*0.2;
const shakeAmt = inten*16*(t>tTie?1:0);

// ===== SISMOGRAFO + LINEA DE TIEMPO =====
const appear = A.p(tMove+0.2,0.6,'softLand');
const prog = A.clamp((t-tTie)/(tDiez-tTie));
const x0=110, x1=970, traceY=570;
if(appear>0){
  A.with(()=>{
    // marco
    A.rect(80,440,920,260,{r:24,stroke:'rgba(255,255,255,0.35)',lw:3});
    A.line([[x0,traceY],[x1,traceY]],{stroke:'rgba(255,255,255,0.15)',lw:2,dash:[10,10]});
    // traza
    const pts=[]; const N=220;
    const endX = A.lerp(x0,x1,prog);
    for(let i=0;i<=N;i++){
      const x=A.lerp(x0,x1,i/N); if(x>endX) break;
      const u=(x-x0)/(x1-x0);
      const env = 8 + 110*Math.min(1,Math.pow(u,0.7))*(0.6+0.4*Math.sin(u*9));
      const y = traceY + env*(Math.sin(x*0.21)*0.6 + Math.sin(x*0.53+1.3)*0.4);
      pts.push([x,y]);
    }
    if(prog<=0) pts.push([x0,traceY],[x0+1,traceY]);
    A.line(pts,{stroke:ac,lw:5});
    const last=pts[pts.length-1];
    const jit = Math.sin(t*60)*inten*40;
    A.line([[last[0],430],[last[0],last[1]+jit*0.3]],{stroke:'#ffffff',lw:3,alpha:0.8});
    A.circle(last[0],last[1]+jit*0.3,10,{fill:'#ffffff',glow:20});
    // linea de tiempo
    const ty=790;
    A.line([[x0,ty],[x1,ty]],{stroke:'rgba(255,255,255,0.4)',lw:6});
    A.line([[x0,ty],[A.lerp(x0,x1,prog),ty]],{stroke:ac,lw:10});
    for(let m=0;m<=10;m++){
      const x=A.lerp(x0,x1,m/10);
      A.line([[x,ty-14],[x,ty+14]],{stroke:'rgba(255,255,255,0.6)',lw:3});
      if(m%5===0) A.text(String(m),x,ty+50,{size:34,color:'rgba(255,255,255,0.7)',weight:'700',align:'center'});
    }
    A.text('min',x1+0,ty-40,{size:28,color:'rgba(255,255,255,0.6)',align:'center'});
    const mx=A.lerp(x0,x1,prog);
    if(t>tTie && t<tDiez+0.05){
      A.label(A.counter(0,10,prog,0)+' min',mx,ty-60,{size:40,bg:ac,color:'#0b1630'});
    }
  },{alpha:appear, y:0, shake:shakeAmt*0.4});
}

// ===== PUEBLO SOBRE CORTE DE SUELO =====
if(appear>0){
  A.with(()=>{
    const gy=1065;
    const groundPts=[[60,gy],[1020,gy],[1020,1120],[60,1120]];
    A.lib.hatch(ctx,groundPts,{angle:0.7,spacing:14,width:2,color:'rgba(255,212,0,0.35)'});
    A.line([[60,gy],[1020,gy]],{stroke:'#ffffff',lw:4});
    const hs=[[180,90,80],[330,120,110],[520,100,90],[700,130,100],[870,90,85]];
    hs.forEach((h,i)=>{
      const [hx,hw,hh]=h;
      const tilt=Math.sin(t*18+i*1.7)*inten*0.06;
      A.with(()=>{
        A.rect(hx-hw/2,gy-hh,hw,hh,{stroke:'#ffffff',lw:3,fill:'#13234a'});
        A.lib.inkPath(ctx,[[hx-hw/2-10,gy-hh],[hx,gy-hh-50],[hx+hw/2+10,gy-hh]],{width:3,color:'#ffffff',closed:true,fill:'#1d3266'});
        A.rect(hx-12,gy-hh*0.55,24,24,{fill:inten>0.5?ac:'rgba(255,255,255,0.3)'});
      },{x:hx,y:gy,rot:tilt});
    });
  },{alpha:appear,shake:shakeAmt});
}

// ===== CALENDARIO =====
const mv=A.p(tMove,0.75,'whip');
const cx=A.lerp(540,540,mv), cy=A.lerp(770,1540,mv), cs=A.lerp(1,0.42,mv)*A.pop(0,0.5);
A.with(()=>{
  const w=520,h=560,l=540-w/2,tp=770-h/2;
  A.rect(l+12,tp+16,w,h,{r:28,fill:'rgba(0,0,0,0.4)'});
  A.rect(l,tp,w,h,{r:28,fill:'#f4f1e8'});
  A.lib.hatch(ctx,[[l+w-70,tp+130],[l+w,tp+130],[l+w,tp+h],[l+w-70,tp+h]],{angle:-0.8,spacing:12,width:1.5,color:'rgba(11,22,48,0.15)'});
  A.rect(l,tp,w,130,{r:28,fill:'#0b1630'});
  A.rect(l,tp+90,w,40,{fill:'#0b1630'});
  for(let i=0;i<4;i++) A.circle(l+90+i*113,tp,14,{fill:'#c9c4b5',stroke:'#0b1630',lw:4});
  const pD=A.p(tDom,0.45,'snapSettle');
  if(pD>0) A.text('DOMINGO',540,tp+78,{size:64,color:ac,weight:'900',align:'center',alpha:pD,scale:1});
  const p22=A.p(t22,0.5,'snapSettle');
  if(p22>0){
    A.with(()=>{A.text(A.counter(1,22,A.clamp((t-t22)/0.35),0),540,tp+330,{size:250,color:'#0b1630',weight:'900',align:'center'});},{x:540,y:tp+300,scale:A.pop(t22,0.45)});
  }
  const pM=A.p(tMay,0.5,'softLand');
  if(pM>0) A.text('MAYO 1960',540,tp+490+(1-pM)*30,{size:66,color:'#c0392b',weight:'900',align:'center',alpha:pM});
},{x:540,y:770,scale:cs,shake:mv>0.9?shakeAmt*0.5:0});
// mueve el calendario: traslación vía segundo with
// (aplicado por desplazamiento: dibujado alrededor de 770, se recoloca abajo)

const ac = A.accent;
A.bg('#0b1630', '#050a18');
const kF = A.k('falla', 0.333), kR = A.k('rompió', 1.0), kKm = A.k('kilómetros:', 3.333, 1);
const kD = A.k('distancia', 5.0), kS = A.k('Santiago', 5.667), kP = A.k('Puerto', 6.333);

const Y0 = 470, Y1 = 1090;
// progreso de la grieta: termina justo en "kilómetros"
const pc = A.p(kR, Math.max(0.5, kKm - kR), 'cruise');
const cracking = t > kR && t < kKm + 0.15;
const shake = cracking ? 7 : (t < kKm + 0.6 ? 7 * (1 - A.clamp((t - kKm - 0.15) / 0.45)) : 0);

// ---- MAPA ----
const r = A.rand(7);
const N = 26, left = [], right = [];
for (let i = 0; i <= N; i++) {
  const y = A.lerp(Y0, Y1, i / N);
  const bend = Math.sin(i / N * 3.1) * 10;
  left.push([500 + bend + (r() - 0.5) * 22, y]);
  right.push([600 + bend * 0.6 + (r() - 0.5) * 26, y]);
}
const poly = left.concat(right.slice().reverse());
const mA = A.p(0, 0.6, 'softLand');

A.with(() => {
  ctx.save();
  ctx.globalAlpha = mA;
  ctx.translate(0, (1 - mA) * 40);
  A.lib.inkPath(ctx, poly, { width: 3, color: '#e8f1ff', closed: true, fill: 'rgba(255,107,53,0.07)' });
  A.lib.hatch(ctx, poly, { angle: 45, spacing: 14, width: 1.2, color: 'rgba(200,220,255,0.28)' });
  A.text('OCÉANO PACÍFICO', 250, 1060, { size: 30, color: 'rgba(170,200,255,0.55)', weight: 700, align: 'center' });
  ctx.restore();

  // ---- PLACA DE NAZCA empujando ----
  const nA = A.p(kF, 0.5, 'softLand');
  if (nA > 0) {
    const push = Math.sin(t * 5) * 6;
    [620, 780, 940].forEach((y, i) => {
      const pi = A.p(kF + i * 0.12, 0.5, 'glide');
      A.arrow(150 + push, y, 380 + push, y, { progress: pi, color: '#9fc3ff', lw: 7, head: 22, alpha: 0.8 * (cracking ? 0.6 : 1) });
    });
    A.text('NAZCA', 250, 560, { size: 38, color: '#9fc3ff', weight: 800, align: 'center', alpha: nA });
  }

  // ---- GRIETA ----
  const FX = 440;
  const cr = A.rand(21), crack = [];
  const M = 40;
  for (let i = 0; i <= M; i++) {
    crack.push([FX + (i % 2 ? 1 : -1) * (6 + cr() * 10), A.lerp(Y0 + 10, Y1 - 10, i / M)]);
  }
  if (pc > 0) {
    A.line(crack, { stroke: ac, lw: 12, alpha: 0.35, progress: pc });
    A.line(crack, { stroke: ac, lw: 6, progress: pc });
    A.line(crack, { stroke: '#ffffff', lw: 2, progress: pc });
    const ty = A.lerp(Y0 + 10, Y1 - 10, pc);
    if (pc < 1) {
      A.lib.glowDot(ctx, FX, ty, 22, { color: ac });
      A.circle(FX, ty, 9, { fill: '#fff', glow: 30 });
      A.particles(14, 3, (i, rnd) => {
        const a = rnd() * Math.PI * 2, d = 20 + ((t * 3 + rnd()) % 1) * 50;
        A.circle(FX + Math.cos(a) * d, ty + Math.sin(a) * d, 3 + rnd() * 3, { fill: i % 2 ? ac : '#fff', alpha: 0.9 });
      });
    }
    for (let j = 0; j < 5; j++) {
      const st = kR + j * (kKm - kR) / 5;
      const yy = A.lerp(Y0 + 10, Y1 - 10, j / 5);
      A.rings(FX, yy, st, { count: 2, speed: 160, gap: 30, maxR: 110, color: ac, lw: 3, alpha: 0.7 });
    }
    // réplicas durante "más o menos"
    if (t > kKm) {
      for (let j = 0; j < 4; j++) {
        A.rings(FX, A.lerp(560, 1000, j / 3), kKm + 0.3 + j * 0.35, { count: 1, speed: 140, maxR: 80, color: ac, lw: 2, alpha: 0.5 });
      }
    }
  }

  // ---- COMPARACIÓN SANTIAGO - PUERTO MONTT ----
  const bp = A.p(kD, 0.7, 'glide');
  if (bp > 0) {
    const BX = 690, mid = (Y0 + Y1) / 2;
    A.arrow(BX, mid, BX, Y0 + 10, { progress: bp, color: '#ffffff', lw: 5, head: 20 });
    A.arrow(BX, mid, BX, Y1 - 10, { progress: bp, color: '#ffffff', lw: 5, head: 20 });
    A.line([[BX - 18, Y0 + 10], [BX + 18, Y0 + 10]], { stroke: '#fff', lw: 4, progress: A.p(kD + 0.5, 0.3) });
    A.line([[BX - 18, Y1 - 10], [BX + 18, Y1 - 10]], { stroke: '#fff', lw: 4, progress: A.p(kD + 0.5, 0.3) });
  }
  const pin = (x, y, st, name) => {
    const s = A.pop(st, 0.45);
    if (s <= 0) return;
    A.with(() => {
      A.circle(x, y, 26, { fill: ac, glow: 30 });
      A.circle(x, y, 10, { fill: '#fff' });
    }, { x, y, scale: s });
    A.line([[x + 28, y], [720, y]], { stroke: '#fff', lw: 3, progress: A.p(st + 0.1, 0.3, 'glide') });
    A.label(name, 870, y, { size: 40, bg: ac, color: '#0b1630', scale: A.pop(st + 0.15, 0.45) });
  };
  pin(560, Y0 + 30, kS, 'SANTIAGO');
  pin(560, Y1 - 30, kP, 'PUERTO MONTT');
}, { x: 540, y: 780, shake });

// ---- CONTADOR (zona secundaria) ----
if (t > kR) {
  const n = Math.round(1000 * pc);
  const str = n >= 1000 ? '1.000' : String(n);
  const land = t > kKm ? A.pop(kKm, 0.5) : 1;
  A.with(() => {
    A.text(str, 540, 1450, { size: 170, color: pc >= 1 ? ac : '#ffffff', weight: 900, align: 'center' });
    A.text('KM', 540, 1570, { size: 60, color: '#ffffff', weight: 800, align: 'center' });
  }, { x: 540, y: 1480, scale: land, alpha: A.p(kR, 0.3, 'softInOut') });
  // regla
  const RX = 190, RW = 700, RY = 1660;
  A.rect(RX, RY, RW, 22, { r: 11, stroke: 'rgba(255,255,255,0.6)', lw: 2 });
  A.rect(RX, RY, RW * pc, 22, { r: 11, fill: ac, glow: 20 });
  for (let i = 0; i <= 10; i++) {
    A.line([[RX + RW * i / 10, RY + 28], [RX + RW * i / 10, RY + (i % 5 ? 40 : 52)]], { stroke: '#cfe0ff', lw: 2, alpha: 0.7 });
  }
}
A.flash(kKm, 0.3, 0.35);

const W=A.W;
A.bg('#06121f','#0b2236');
const ac=A.accent, amber='#E0A35A';
const tZ=A.k('zonas',0.667), tS=A.k('suelo',1.333), tH=A.k('hundió',2.0), tA=A.k('agua',4.0), tN=A.k('nunca',5.333), tSec=A.k('secarse',6.333);
const g0=830, drop=190, fx=340, bot=1125;
const intro=A.p(0,0.8,'softLand');
const iy=(1-intro)*320;
const pd=A.p(tH,0.45,'crashIn');
const dy=drop*pd;
const sh=(t>tH+0.3&&t<tH+1.1)?16*(1-(t-tH-0.3)/0.8):((t>tS&&t<tH)?3:0);
const zoom=1+0.035*(t/A.dur);
const tM=tH+0.3;
A.with(()=>{
ctx.save();ctx.beginPath();ctx.rect(-40,420,W+80,bot-420);ctx.clip();
ctx.translate(0,iy);
const L=[[-40,g0],[fx,g0],[fx-25,bot+40],[-40,bot+40]];
A.lib.inkPath(ctx,L,{width:4,color:amber,closed:true,fill:'#241a12'});
A.lib.hatch(ctx,L,{angle:0.7,spacing:22,width:1.5,color:'rgba(224,163,90,0.25)'});
A.line([[-40,g0+70],[fx-5,g0+70]],{stroke:amber,lw:2,alpha:0.4});
A.line([[150,g0],[150,g0-90]],{stroke:'#fff',lw:6});
A.circle(150,g0-125,48,{stroke:'#fff',lw:4,fill:'#0e2a20'});
const R=[[fx,g0+dy],[W+40,g0+dy],[W+40,bot+60],[fx-25,bot+60]];
A.lib.inkPath(ctx,R,{width:4,color:amber,closed:true,fill:'#2a1e14'});
A.lib.hatch(ctx,R,{angle:-0.7,spacing:22,width:1.5,color:'rgba(224,163,90,0.25)'});
A.line([[fx,g0+70+dy],[W+40,g0+70+dy]],{stroke:amber,lw:2,alpha:0.4});
const posts=[460,600,740,880,1020];
posts.forEach(px=>{A.line([[px,g0+dy],[px,g0+dy-75]],{stroke:'#fff',lw:6});});
A.line([[440,g0+dy-55],[1060,g0+dy-55]],{stroke:'#fff',lw:2,alpha:0.8});
A.line([[440,g0+dy-30],[1060,g0+dy-30]],{stroke:'#fff',lw:2,alpha:0.8});
const cp=A.p(tZ,0.6,'glide');
const glowA=t<tH+0.6?0.6+0.4*Math.sin(t*12):0.5;
A.line([[fx,g0-10],[fx-8,g0+90],[fx+6,g0+170],[fx-15,g0+260],[fx-25,bot+40]],{stroke:ac,lw:6,progress:cp,alpha:glowA});
